    public static Geometry GetGeometry(string iconName)
    {
        if (Cache.TryGetValue(iconName, out var cached))
            return cached;

        if (!Paths.TryGetValue(iconName, out var pathData))
            pathData = Paths["translate"];

        var geometry = StreamGeometry.Parse(pathData);
        Cache[iconName] = geometry;
        return geometry;
    }
}
